        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local ex = { lp.Character }
        local live = Workspace:FindFirstChild("Live"); if live then ex[#ex + 1] = live end
        for _, pl in ipairs(Players:GetPlayers()) do if pl.Character then ex[#ex + 1] = pl.Character end end
        params.FilterDescendantsInstances = ex
        local hit = Workspace:Raycast(Vector3.new(nx, hp.Y + 3, nz), Vector3.new(0, -800, 0), params)
        local ny = hp.Y
        if hit then ny = hp.Y + math.clamp((hit.Position.Y + CFLY_HOVER) - hp.Y, -14, 14) end
        head.CFrame = CFrame.new(nx, ny, nz) * (head.CFrame - head.CFrame.Position)
    end
    return false
end
local PathfindingService = game:GetService("PathfindingService")
local function computePathPoints(toPos)
    local h = hrp(); if not h or typeof(toPos) ~= "Vector3" then return nil end
    local path
    local okc = pcall(function()
        path = PathfindingService:CreatePath({ AgentRadius = 3, AgentHeight = 5, AgentCanJump = false, WaypointSpacing = 8 })
    end)
    if not okc or not path then return nil end
    local ok = pcall(function() path:ComputeAsync(h.Position, toPos) end)
    if not ok or path.Status ~= Enum.PathStatus.Success then return nil end
    local pts = {}
    for _, wp in ipairs(path:GetWaypoints()) do pts[#pts + 1] = wp.Position end
    return (#pts > 0) and pts or nil
end
local function cflyPathTo(targetPos, stopDist, keepGoing)
    if typeof(targetPos) ~= "Vector3" then return false end
    local pts = computePathPoints(targetPos)
    if not pts then return cflyGoto(targetPos, stopDist, keepGoing) end
    for i = 1, #pts do
        if keepGoing and not keepGoing() then return false end
        local sd = (i == #pts) and (stopDist or 3) or 6
        cflyGoto(pts[i], sd, keepGoing)
    end
    if keepGoing and not keepGoing() then return false end
    return cflyGoto(targetPos, stopDist, keepGoing)
end
local function regrabDropped(keepGoing, dropPos, matchFn)
    local t0 = os.clock()
    while RUNNING and (not keepGoing or keepGoing()) and not isCarrying() and os.clock() - t0 < 10 do
        local h = hrp(); local anchor = dropPos or (h and h.Position)
        local best, bestD
        for _, m in ipairs(scanLooseFriends()) do
            if (not matchFn) or matchFn(m) then
                local p = pivotPos(m)
                if p and anchor then local dd = (p - anchor).Magnitude; if dd < 500 and (not bestD or dd < bestD) then best, bestD = m, dd end end
            end
        end
        if best then
            local p = pivotPos(best)
            if p then tpTo(p, 0) end
            doStealLoose(best)
        end
        task.wait(0.15)
    end
    return isCarrying()
end
local maneuverRunning = false
local function cflyManeuver(keep, matchFn)
    keep = keep or function() return true end
    if maneuverRunning then return end
    maneuverRunning = true
    cflyExit(); task.wait(0.05)
    pcall(function()
        local g1 = baseGoalPos()
        if g1 then cflyPathTo(g1, 3, function() return keep() and isCarrying() and not eggPastCommon() end) end
        cflyExit(); task.wait(0.1)
        if isCarrying() and eggPastCommon() then fireRemote("Drop Friend"); task.wait(0.45) end
        if not isCarrying() then regrabDropped(keep, hrp() and hrp().Position, matchFn) end
        local guard = os.clock()
        while keep() and isCarrying() and os.clock() - guard < 30 do
            local g = baseGoalPos()
            local atBase = false
            if g then
                cflyPathTo(g, 3, function() return keep() and isCarrying() end)
                local h = hrp()
                if h and (Vector3.new(h.Position.X, 0, h.Position.Z) - Vector3.new(g.X, 0, g.Z)).Magnitude <= 10 then atBase = true end
            end
            if atBase then
                cflyExit(); task.wait(0.1)
                pcall(placeHeld); task.wait(0.2)
                if isCarrying() then fireRemote("Drop Friend"); task.wait(0.3) end
                break
            end
            task.wait(0.05)
        end
    end)
    cflyExit()
    maneuverRunning = false
end
onClean(function() maneuverRunning = false; cflyExit() end)
local hopping = false
local function httpGetJson(url)
    local body
    local req = (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
        or http_request or request or (getgenv and getgenv().request)
    if req then local ok, res = pcall(req, { Url = url, Method = "GET" }); if ok and type(res) == "table" then body = res.Body or res.body end end
    if not body or body == "" then local ok, res = pcall(function() return game:HttpGet(url) end); if ok then body = res end end
    if not body or body == "" then return nil end
    local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
    if ok then return data end
    return nil
end
local function serverHop(pref, notify)
    if hopping then return end
    hopping = true
    local placeId = game.PlaceId
    local list, cursor, scanned = {}, nil, 0
    for _ = 1, 10 do
        local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(placeId)
        if cursor then url = url .. "&cursor=" .. cursor end
        local data = httpGetJson(url)
        if not data or type(data.data) ~= "table" then break end
        for _, s in ipairs(data.data) do
            scanned += 1
            if type(s.playing) == "number" and s.id ~= game.JobId and s.playing < (s.maxPlayers or 999) then list[#list + 1] = s end
        end
        if data.nextPageCursor and data.nextPageCursor ~= "" then cursor = data.nextPageCursor else break end
        task.wait(0.1)
    end
    if #list == 0 then notify(scanned == 0 and "Hop: API blocked by executor" or "Hop: no joinable server"); hopping = false; return end
    if pref == "Highest Players" then table.sort(list, function(a, b) return a.playing > b.playing end)
    else table.sort(list, function(a, b) return a.playing < b.playing end) end
    notify(("Hop: %d servers found"):format(#list))
    local idx, conn = 0, nil
    local function tryNext()
        idx = idx + 1
        local s = list[idx]
        if not s then if conn then conn:Disconnect() end; hopping = false; notify("Hop: all failed"); return end
        pcall(function() TeleportService:TeleportToPlaceInstance(placeId, s.id, lp) end)
    end
    conn = TeleportService.TeleportInitFailed:Connect(function(who) if who == lp then task.wait(0.5); tryNext() end end)
    tryNext()
    task.delay(25, function() if conn then conn:Disconnect() end; hopping = false end)
end

